// Grafana webhook gövdesini okunur Türkçe mesajlara çevirir (her alarm için bir öğe).
const body = $input.first().json.body ?? $input.first().json;
const SEV = {
  kritik: { icon: '🔴', label: 'KRİTİK' },
  uyari:  { icon: '🟠', label: 'UYARI' },
  bilgi:  { icon: '🔵', label: 'BİLGİ' },
};
const fmtTime = (iso) => new Date(iso).toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul' });

return (body.alerts ?? []).map((a) => {
  const sev = SEV[a.labels?.onem] ?? { icon: '⚪', label: (a.labels?.onem ?? '').toUpperCase() };
  const resolved = a.status === 'resolved';
  const title = resolved
    ? `✅ Düzeldi · ${a.labels?.alertname ?? 'Alarm'}`
    : `${sev.icon} ${sev.label} · ${a.labels?.alertname ?? 'Alarm'}`;
  const lines = [
    title,
    a.annotations?.summary ?? '',
    resolved ? '' : (a.annotations?.description ?? ''),
    `🕒 ${fmtTime(resolved ? a.endsAt : a.startsAt)}`,
    a.dashboardURL || a.generatorURL ? `🔗 ${a.dashboardURL || a.generatorURL}` : '',
  ].filter(Boolean);
  return {
    json: {
      durum: resolved ? 'duzeldi' : 'tetiklendi',
      onem: a.labels?.onem ?? '',
      baslik: title,
      mesaj: lines.join('\n'),
      alarm: a.labels?.alertname ?? '',
      zaman: resolved ? a.endsAt : a.startsAt,
    },
  };
});
